3	@{
4	    if (Model?.Any() != true) { return; }
5	}
6	
7	<div class="umb-block-grid__layout-container">
8	    @foreach (var item in Model)
9	    {
10	
11	        <div
12	            class="umb-block-grid__layout-item"
