@using Umbraco.Extensions
@model Umbraco.Bench.Umbraco.Models.ImageBlock

@{
    var image = Model.Image;
}

<div class="image-block" style="margin: 20px 0;">
    @if (image != null)
    {
        <figure style="margin: 0;">
            <img src="@image.GetCropUrl(800, 500)" alt="@Model.Caption" style="width: 100%; height: auto; border-radius: 8px; box-shadow: 0 2px 8px rgba(0,0,0,0.1);" />
