using Microsoft.Data.Sqlite;

var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();

using var conn = new SqliteConnection(connString);
conn.Open();

// List all tables
var tables = new List<string>();
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        tables.Add(reader.GetString(0));
}
Console.WriteLine("=== Tables ===");
Console.WriteLine(string.Join(", ", tables));

// Search for content/property data tables
var interestingTables = tables.Where(t =>
    t.ToLower().Contains("content") ||
    t.ToLower().Contains("property") ||
    t.ToLower().Contains("document") ||
    t.ToLower().Contains("version")).ToList();

foreach (var table in interestingTables.Take(5))
{
    try
    {
        using var schemaCmd = conn.CreateCommand();
        schemaCmd.CommandText = $"SELECT sql FROM sqlite_master WHERE name = '{table}'";
        var schema = schemaCmd.ExecuteScalar()?.ToString() ?? "";
        Console.WriteLine($"\n=== {table} schema ===");
        Console.WriteLine(schema);

        using var countCmd = conn.CreateCommand();
        countCmd.CommandText = $"SELECT COUNT(*) FROM \"{table}\"";
        var count = (long)(countCmd.ExecuteScalar() ?? 0);
        Console.WriteLine($"Row count: {count}");

        if (count > 0)
        {
            using var dataCmd = conn.CreateCommand();
            dataCmd.CommandText = $"SELECT * FROM \"{table}\" LIMIT 2";
            using var reader = dataCmd.ExecuteReader();
            var cols = new List<string>();
            for (int i = 0; i < reader.FieldCount; i++)
                cols.Add(reader.GetName(i));
            Console.WriteLine($"Columns: {string.Join(", ", cols)}");

            while (reader.Read())
            {
                Console.WriteLine("--- Row ---");
                for (int i = 0; i < reader.FieldCount; i++)
                {
