using Microsoft.Data.Sqlite;
using System.Text;

var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();

using var conn = new SqliteConnection(connString);
conn.Open();

// Get published cache data
Console.WriteLine("=== cmsContentNu - Published Cache Data ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT nu.nodeId, nu.published, nu.dataRaw
        FROM cmsContentNu nu
        JOIN umbracoNode n ON n.id = nu.nodeId
        WHERE nu.published = 1
        ORDER BY nu.nodeId
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        var nodeId = reader.GetInt32(0);
        var published = reader.GetInt32(1);

        // Read the BLOB
        byte[]? blob = null;
        if (!reader.IsDBNull(2))
        {
            var buffer = new byte[65536];
            long bytesRead;
            using (var stream = reader.GetStream(2))
            {
                using var ms = new MemoryStream();
                stream.CopyTo(ms);
                blob = ms.ToArray();
            }
        }

        if (blob != null)
        {
            var text = Encoding.UTF8.GetString(blob);

            // Check if it's JSON (likely gzipped or raw JSON)
            if (text.StartsWith("{"))
            {
                // Check for block grid content
                var isBlockGrid = text.Contains("BlockGrid") || text.Contains("contentData");

                Console.WriteLine($"\n--- NodeId={nodeId}, Published={published} ({(isBlockGrid ? "CONTAINS BLOCK GRID" : "no blocks")}) ---");

                if (isBlockGrid)
                {
                    // Find the block grid property
                    var propStart = text.IndexOf("\"content\"");
                    if (propStart > 0)
                    {
                        var sliceLen = Math.Min(text.Length - propStart, 2000);
                        Console.WriteLine(text.Substring(propStart, sliceLen));
                    }
                    else
                    {
                        Console.WriteLine(text.Substring(0, Math.Min(text.Length, 2000)));
                    }
                }
                else
                {
                    Console.WriteLine(text.Substring(0, Math.Min(text.Length, 500)));
                }
            }
            else if (blob[0] == 0x1F && blob[1] == 0x8B)
            {
                Console.WriteLine($"\n--- NodeId={nodeId}, Published={published} (GZIPPED) ---");
                Console.WriteLine($"Compressed: {blob.Length} bytes");
            }
            else
            {
                Console.WriteLine($"\n--- NodeId={nodeId}, Published={published} (raw {blob.Length} bytes) ---");
                Console.WriteLine(text.Substring(0, Math.Min(text.Length, 500)));
            }
        }
        else
        {
            Console.WriteLine($"\n--- NodeId={nodeId}, Published={published} (NULL) ---");
        }
    }
}

// Also get the full textValue for the content property (block grid) to see editorAlias format
Console.WriteLine("\n\n=== Full block grid values from umbracoPropertyData ===");
