using Microsoft.Data.Sqlite;
using System.IO.Compression;
using System.Text;

var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();

using var conn = new SqliteConnection(connString);
conn.Open();

// Check umbracoDocumentVersion schema
Console.WriteLine("=== umbracoDocumentVersion schema ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT sql FROM sqlite_master WHERE name = 'umbracoDocumentVersion'";
    Console.WriteLine(cmd.ExecuteScalar()?.ToString() ?? "N/A");
}

Console.WriteLine("\n=== umbracoDocument schema ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT sql FROM sqlite_master WHERE name = 'umbracoDocument'";
    Console.WriteLine(cmd.ExecuteScalar()?.ToString() ?? "N/A");
}

// Check blog post documents
Console.WriteLine("\n=== Blog Content Documents ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT d.nodeId, d.published, d.edited,
               dv.versionId, dv.currentPublishedVersionId, dv.date, dv.text
        FROM umbracoDocument d
        JOIN umbracoDocumentVersion dv ON dv.nodeId = d.nodeId
        JOIN umbracoNode n ON n.id = d.nodeId
        WHERE n.text LIKE '%MCP%'
        ORDER BY d.nodeId, dv.date DESC
    ";
    using var reader = cmd.ExecuteReader();
    var cols = new List<string>();
    for (int i = 0; i < reader.FieldCount; i++) cols.Add(reader.GetName(i));
    Console.WriteLine($"Columns: {string.Join(", ", cols)}");
    while (reader.Read())
    {
        Console.WriteLine($"  NodeId={reader[0]}, Published={reader[1]}, Edited={reader[2]}, VersionId={reader[3]}, PubVerId={reader[4]}, Date={reader[5]}, Text='{reader[6]}'");
    }
}

// Check published cache
Console.WriteLine("\n=== Published Cache ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT nu.nodeId, n.text, LENGTH(nu.dataRaw) as blobSize FROM cmsContentNu nu JOIN umbracoNode n ON n.id = nu.nodeId WHERE nu.published = 1 ORDER BY nu.nodeId";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"  NodeId={reader[0]}, '{reader[1]}', blobSize={reader[2]}");
}

// Decompress the published cache for blog posts
Console.WriteLine("\n=== Blog Post Published Cache (decompressed) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = "SELECT nu.nodeId, nu.dataRaw FROM cmsContentNu nu WHERE nu.published = 1 AND nu.nodeId IN (1103, 1104)";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        var nodeId = reader.GetInt32(0);
        byte[] blob;
        using (var stream = reader.GetStream(1))
        using (var ms = new MemoryStream())
        {
            stream.CopyTo(ms);
            blob = ms.ToArray();
        }

        string decompressed;
        using var compressed = new MemoryStream(blob);
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        using var result = new MemoryStream();
        gzip.CopyTo(result);
        decompressed = Encoding.UTF8.GetString(result.ToArray());

        Console.WriteLine($"\n--- NodeId={nodeId} ({decompressed.Length} chars) ---");
        Console.WriteLine(decompressed);
    }
}

conn.Close();

