using Microsoft.Data.Sqlite;
using System.IO.Compression;
using System.Text;

var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();

using var conn = new SqliteConnection(connString);
conn.Open();

// Check node structure - which nodes are content
Console.WriteLine("=== Content Node Tree ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT n.id, n.parentId, n.level, n.sortOrder, n.uniqueId, COALESCE(n.text, '(no text)') as text,
               n.nodeObjectType,
               CASE WHEN n.nodeObjectType = 'b6fbc602-4c5e-4d4d-8a2b-5b2c6e8a4f4d' THEN 'Document'
                    WHEN n.nodeObjectType = 'f38a7f8e-5a7e-4f3e-8e0a-8f5f6e7d8c9b' THEN 'DocumentType'
                    WHEN n.nodeObjectType = 'c66ba902-7b8e-4f3e-8e0a-8f5f6e7d8c9b' THEN 'MediaType'
                    WHEN n.nodeObjectType = '4fb2c3e8-5a7e-4f3e-8e0a-8f5f6e7d8c9b' THEN 'Template'
                    WHEN n.nodeObjectType = 'f4e3f2e1-d5c6-4b7a-9a8b-7c6d5e4f3a2b' THEN 'DataType'
                    WHEN n.nodeObjectType = 'a4b5c6d7-e8f9-4a1b-2c3d-4e5f6a7b8c9d' THEN 'Media'
                    WHEN n.nodeObjectType = 'ea7b8c9d-1e2f-4a3b-8c7d-6e5f4a3b2c1d' THEN 'Member'
                    ELSE 'Other: ' + COALESCE(n.nodeObjectType, 'NULL')
               END as typeDesc
        FROM umbracoNode n
        ORDER BY n.level, n.sortOrder
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        var id = reader.GetInt32(0);
        var parentId = reader.GetInt32(1);
        var level = reader.GetInt32(2);
        var sortOrder = reader.GetInt32(3);
        var uniqueId = reader.GetGuid(4);
        var text = reader.GetString(5);
        var typeDesc = reader.GetString(7);
        var indent = new string(' ', Math.Max(0, (level - 1) * 4));
        Console.WriteLine($"{indent}NodeId={id}, Parent={parentId}, L{level}, Sort={sortOrder}, '{text}' - {typeDesc}");
    }
}

// Check templates
Console.WriteLine("\n=== Templates ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT t.nodeId, n.text, t.alias
        FROM cmsTemplate t
        JOIN umbracoNode n ON n.id = t.nodeId
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"  NodeId={reader.GetInt32(0)}, Name='{reader.GetString(1)}', Alias='{reader.GetString(2)}'");
}

// Check document types
Console.WriteLine("\n=== Document Types ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT ct.nodeId, n.text, ct.alias, ct.isElement
        FROM cmsContentType ct
        JOIN umbracoNode n ON n.id = ct.nodeId
        ORDER BY ct.isElement, ct.nodeId
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"  NodeId={reader.GetInt32(0)}, Name='{reader.GetString(1)}', Alias='{reader.GetString(2)}', IsElement={reader.GetInt32(3)}");
}

// Check document type -> template mapping
Console.WriteLine("\n=== Document Type -> Template Mapping ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT dt.contentTypeNodeId,
               COALESCE((SELECT n.text FROM umbracoNode n WHERE n.id = dt.contentTypeNodeId), '?') as docTypeName,
               dt.templateNodeId,
               COALESCE((SELECT n.text FROM umbracoNode n WHERE n.id = dt.templateNodeId), '?') as templateName,
               dt.IsDefault
        FROM cmsDocumentType dt
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"  ContentType={reader.GetInt32(0)} ('{reader.GetString(1)}') -> Template={reader.GetInt32(2)} ('{reader.GetString(3)}'), IsDefault={reader.GetInt32(4)}");
}

// Check blog post nodes specifically
Console.WriteLine("\n=== Blog Post Document Details ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT dv.nodeId, dv.currentPublishedVersionId, dv.published, dv.edited, dv.newest
        FROM umbracoDocumentVersion dv
        JOIN umbracoNode n ON n.id = dv.nodeId
        WHERE n.text LIKE '%MCP%'
        ORDER BY dv.nodeId, dv.newest DESC
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
        Console.WriteLine($"  NodeId={reader.GetInt32(0)}, PubVersionId={reader.GetInt32(1)}, Published={reader.GetInt32(2)}, Edited={reader.GetInt32(3)}, Newest={reader.GetInt32(4)}");
}

// Check published cache content - decompress gzip
Console.WriteLine("\n=== Published Cache Content (decompressed) ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT nu.nodeId, nu.dataRaw
        FROM cmsContentNu nu
        WHERE nu.published = 1 AND nu.dataRaw IS NOT NULL
    ";
    using var reader = cmd.ExecuteReader();
    while (reader.Read())
    {
        var nodeId = reader.GetInt32(0);
        byte[] blob;
        using (var stream = reader.GetStream(1))
        using (var ms = new MemoryStream())
        {
            stream.CopyTo(ms);
            blob = ms.ToArray();
        }

        string decompressed;
        if (blob.Length > 2 && blob[0] == 0x1F && blob[1] == 0x8B)
        {
            using var compressed = new MemoryStream(blob);
            using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
            using var result = new MemoryStream();
            gzip.CopyTo(result);
            decompressed = Encoding.UTF8.GetString(result.ToArray());
        }
        else
        {
            decompressed = Encoding.UTF8.GetString(blob);
        }

        Console.WriteLine($"\n--- NodeId={nodeId} ({decompressed.Length} chars) ---");
        // Find block grid content
        var contentIdx = decompressed.IndexOf("\"content\"");
        if (contentIdx > 0 && decompressed.Contains("BlockGrid"))
        {
            var start = Math.Max(0, contentIdx - 50);
            var len = Math.Min(decompressed.Length - start, 1200);
            Console.WriteLine(decompressed.Substring(start, len));
        }
        else
        {
            Console.WriteLine(decompressed.Substring(0, Math.Min(decompressed.Length, 500)));
        }
    }
}

conn.Close();

