using System;
using System.Threading;
using System.Threading.Tasks;
using Asp.Versioning;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Umbraco.Cms.Api.Management.Factories;
using Umbraco.Cms.Api.Management.ViewModels.Document;
using Umbraco.Cms.Core;
using Umbraco.Cms.Core.Models.ContentEditing;
using Umbraco.Cms.Core.Security;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Core.Services.OperationStatus;

namespace Umbraco.Cms.Api.Management.Controllers.Document;

/// <summary>
/// Controller responsible for handling update operations on documents in the management API.
/// </summary>
[ApiVersion("1.0")]
public class UpdateDocumentController : UpdateDocumentControllerBase
{
	private readonly IContentEditingService _contentEditingService;

	private readonly IDocumentEditingPresentationFactory _documentEditingPresentationFactory;

	private readonly IBackOfficeSecurityAccessor _backOfficeSecurityAccessor;

	/// <summary>
	/// Initializes a new instance of the <see cref="T:Umbraco.Cms.Api.Management.Controllers.Document.UpdateDocumentController" /> class.
	/// </summary>
	/// <param name="authorizationService">Service for verifying user permissions.</param>
	/// <param name="contentEditingService">Service for managing content updates.</param>
	/// <param name="documentEditingPresentationFactory">Factory for creating document editing presentation models.</param>
	/// <param name="backOfficeSecurityAccessor">Accessor for the back office user security context.</param>
	public UpdateDocumentController(IAuthorizationService authorizationService, IContentEditingService contentEditingService, IDocumentEditingPresentationFactory documentEditingPresentationFactory, IBackOfficeSecurityAccessor backOfficeSecurityAccessor)
		: base(authorizationService)
	{
		_contentEditingService = contentEditingService;
		_documentEditingPresentationFactory = documentEditingPresentationFactory;
		_backOfficeSecurityAccessor = backOfficeSecurityAccessor;
	}

	/// <summary>Updates the specified document with new details provided in the request model.</summary>
	/// <param name="cancellationToken">A token to monitor for cancellation requests.</param>
	/// <param name="id">The unique identifier of the document to update.</param>
	/// <param name="requestModel">The model containing the updated document details.</param>
	/// <returns>An <see cref="T:Microsoft.AspNetCore.Mvc.IActionResult" /> representing the outcome of the update operation.</returns>
	[HttpPut("{id:guid}")]
	[MapToApiVersion("1.0")]
	[ProducesResponseType(200)]
	[ProducesResponseType(typeof(ProblemDetails), 400)]
	[ProducesResponseType(typeof(ProblemDetails), 404)]
	[EndpointSummary("Updates a document.")]
	[EndpointDescription("Updates a document identified by the provided Id with the details from the request model.")]
	public async Task<IActionResult> Update(CancellationToken cancellationToken, Guid id, UpdateDocumentRequestModel requestModel)
	{
		return await HandleRequest(id, requestModel, async delegate
		{
			ContentUpdateModel val = _documentEditingPresentationFactory.MapUpdateModel(requestModel);
			Attempt<ContentUpdateResult, ContentEditingOperationStatus> val2 = await _contentEditingService.UpdateAsync(id, val, ManagementApiControllerBase.CurrentUserKey(_backOfficeSecurityAccessor));
			IActionResult result;
			if (!val2.Success)
			{
				result = ContentEditingOperationStatusResult(val2.Status);
			}
			else
			{
				IActionResult actionResult = Ok();
				result = actionResult;
			}
			return result;
		});
	}
}

using System;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Umbraco.Cms.Api.Management.ViewModels.Document;
using Umbraco.Cms.Core.Security.Authorization;
using Umbraco.Extensions;

namespace Umbraco.Cms.Api.Management.Controllers.Document;

/// <summary>
/// Serves as the base controller for handling update operations on documents within the Umbraco CMS Management API.
/// Provides common functionality for derived controllers that manage document updates.
/// </summary>
public abstract class UpdateDocumentControllerBase : DocumentControllerBase
{
	private readonly IAuthorizationService _authorizationService;

	protected UpdateDocumentControllerBase(IAuthorizationService authorizationService)
	{
		_authorizationService = authorizationService;
	}

	protected async Task<IActionResult> HandleRequest(Guid id, UpdateDocumentRequestModel requestModel, Func<Task<IActionResult>> authorizedHandler)
	{
		return await HandleRequest(id, authorizedHandler);
	}

	protected async Task<IActionResult> HandleRequest(Guid id, Func<Task<IActionResult>> authorizedHandler)
	{
		if (!(await _authorizationService.AuthorizeResourceAsync(base.User, (IPermissionResource)(object)ContentPermissionResource.WithKeys("Umb.Document.Update", id), "ContentPermissionByResource")).Succeeded)
		{
			return Forbidden();
		}
		return await authorizedHandler();
	}
}

