    while (reader.Read())
    {
        var nodeId = reader.GetInt32(0);
        var data = reader.IsDBNull(1) ? null : reader.GetString(1);
        if (data != null)
        {
            Console.WriteLine($"\n--- NodeId={nodeId}, dataLen={data.Length} ---");
            // Show first 3000 chars
            Console.WriteLine(data.Substring(0, Math.Min(3000, data.Length)));

            if (data.Contains("contentData"))
            {
                var idx = data.IndexOf("contentData");
                Console.WriteLine($"\n  contentData found at position {idx}");
            }
        }
        else
        {
            Console.WriteLine($"\n--- NodeId={nodeId} - data is NULL ---");
        }
    }
}

