	{
		ContentCreateModel obj = MapContentEditingModel<ContentCreateModel>((ContentModelBase<DocumentValueModel, DocumentVariantRequestModel>)(object)requestModel);
		((ContentCreationModelBase)obj).Key = requestModel.Id;
		((ContentCreationModelBase)obj).ContentTypeKey = requestModel.DocumentType.Id;
		obj.TemplateKey = requestModel.Template?.Id;
		((ContentCreationModelBase)obj).ParentKey = requestModel.Parent?.Id;
		return obj;
	}

	/// <inheritdoc />
