	{
		DocumentValueModel[] values = MapValuesToRequestModel(((IContentBase)content).Properties);
		DocumentVariantRequestModel[] variants = MapVariantsToRequestModel(content);
		Guid? guid;
		if (((ITemplatedContent)content).TemplateId.HasValue)
		{
			ITemplate obj = await _templateService.GetAsync(((ITemplatedContent)content).TemplateId.Value);
			guid = ((obj != null) ? new Guid?(((IEntity)obj).Key) : ((Guid?)null));
		}
		else
		{
			guid = null;
		}
		Guid? guid2 = guid;
		return new UpdateDocumentRequestModel
		{
			Values = values,
			Variants = variants,
			Template = (guid2.HasValue ? new ReferenceByIdModel
			{
				Id = guid2.Value
			} : null)
		};
	}

	/// <inheritdoc />
	public ContentPatchModel MapPatchModel(PatchDocumentRequestModel requestModel)
	{
		PatchOperationModel[] operations = requestModel.Operations.Select((PatchOperationRequestModel op) => new PatchOperationModel
		{
			Op = MapOperationType(op.Op),
			Path = op.Path,
			Value = op.Value
		}).ToArray();
		return new ContentPatchModel
		{
			Operations = operations
		};
	}

	/// <inheritdoc />
	public ValidateContentUpdateModel MapValidateUpdateModel(ValidateUpdateDocumentRequestModel requestModel)
	{
		ValidateContentUpdateModel obj = MapUpdateContentModel<ValidateContentUpdateModel>((UpdateDocumentRequestModel)requestModel);
		obj.Cultures = requestModel.Cultures;
		return obj;
	}

	private DocumentValueModel[] MapValuesToRequestModel(IPropertyCollection properties)
	{
		Dictionary<string, IDataEditor> missingPropertyEditors = new Dictionary<string, IDataEditor>();
		return EnumerableExtensions.WhereNotNull<DocumentValueModel>(((IEnumerable<IProperty>)properties).SelectMany((IProperty property) => property.Values.Select(delegate(IPropertyValue propertyValue)
