				missingPropertyEditors[property.PropertyType.PropertyEditorAlias] = value;
			}
			DocumentValueModel documentValueModel = new DocumentValueModel();
			((ValueModelBase)documentValueModel).Culture = propertyValue.Culture;
			((ValueModelBase)documentValueModel).Segment = propertyValue.Segment;
			((ValueModelBase)documentValueModel).Alias = property.Alias;
			((ValueModelBase)documentValueModel).Value = value.GetValueEditor().ToEditor(property, propertyValue.Culture, propertyValue.Segment);
			return documentValueModel;
		}))).ToArray();
	}

	private DocumentVariantRequestModel[] MapVariantsToRequestModel(IContent content)
	{
		IPropertyValue[] source = ((IEnumerable<IProperty>)((IContentBase)content).Properties).SelectMany((IProperty propertyCollection) => propertyCollection.Values).ToArray();
