    {
        Console.WriteLine($"--- Property ---");
        for (int i = 0; i < reader.FieldCount; i++)
        {
            var name = cols[i];
            var val = reader.GetValue(i);
            if (val is DBNull)
                Console.WriteLine($"  {name}: NULL");
            else if (name == "value" && val is string str && str.Length > 200)
                Console.WriteLine($"  {name}: {str.Substring(0, 200)}... (length={str.Length})");
            else
                Console.WriteLine($"  {name}={val}");
        }
    }
}

// Also check what property type "content" maps to
Console.WriteLine("\n=== Property Types for BlogPost content type ===");
using (var cmd = conn.CreateCommand())
{
    cmd.CommandText = @"
        SELECT pt.id, pt.contentTypeId, pt.propertyTypeGroupId, pt.Alias, pt.Name,
