        for (int i = 0; i < reader.FieldCount; i++)
        {
            var name = cols[i];
            var val = reader.GetValue(i);
            if (val is DBNull)
                Console.WriteLine($"  {name}: NULL");
            else if (name.Contains("dataRaw") || name.Contains("Data"))
            {
                var bytes = (byte[])val;
                Console.WriteLine($"  {name}: BLOB ({bytes.Length} bytes)");
                // Show first 200 bytes as hex for analysis
                var hex = BitConverter.ToString(bytes.Take(200).ToArray());
                Console.WriteLine($"    Hex: {hex}");
                // Try to detect format - check first bytes
                if (bytes.Length >= 4)
                {
                    Console.WriteLine($"    First 4 bytes: {bytes[0]:X2} {bytes[1]:X2} {bytes[2]:X2} {bytes[3]:X2}");
                    // Check for known compression headers
                    if (bytes[0] == 0x1F && bytes[1] == 0x8B) Console.WriteLine("    Format: GZip");
                    else if (bytes[0] == 0x78) Console.WriteLine("    Format: ZLib/Deflate");
                    else if (bytes[0] == 0x28 && bytes[1] == 0xB5 && bytes[2] == 0x2F && bytes[3] == 0xFD) Console.WriteLine("    Format: Brotli");
