using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Umbraco.Cms.Core.Configuration.Models;
using Umbraco.Cms.Core.Models;
using Umbraco.Cms.Core.Models.ContentEditing;
using Umbraco.Cms.Core.PropertyEditors;
using Umbraco.Cms.Core.Scoping;
using Umbraco.Cms.Core.Services.Filters;
using Umbraco.Cms.Core.Services.OperationStatus;

namespace Umbraco.Cms.Core.Services;

/// <summary>
/// Provides services for creating, updating, and managing content (documents).
/// </summary>
internal sealed class ContentEditingService : ContentEditingServiceWithSortingBase<IContent, IContentType, IContentService, IContentTypeService>, IContentEditingService
{
	private readonly ITemplateService _templateService;

	private readonly ILogger<ContentEditingService> _logger;

	/// <inheritdoc />
	protected override string? RelateParentOnDeleteAlias => "relateParentDocumentOnDelete";

	/// <summary>
	/// Initializes a new instance of the <see cref="T:Umbraco.Cms.Core.Services.ContentEditingService" /> class.
	/// </summary>
	/// <param name="contentService">The content service.</param>
	/// <param name="contentTypeService">The content type service.</param>
	/// <param name="propertyEditorCollection">The property editor collection.</param>
	/// <param name="dataTypeService">The data type service.</param>
	/// <param name="templateService">The template service.</param>
	/// <param name="logger">The logger.</param>
	/// <param name="scopeProvider">The scope provider.</param>
	/// <param name="userIdKeyResolver">The user ID key resolver.</param>
	/// <param name="treeEntitySortingService">The tree entity sorting service.</param>
	/// <param name="contentValidationService">The content validation service.</param>
	/// <param name="userService">The user service.</param>
	/// <param name="languageService">The language service.</param>
	/// <param name="optionsMonitor">The content settings options monitor.</param>
	/// <param name="relationService">The relation service.</param>
	/// <param name="contentTypeFilters">The content type filter collection.</param>
	public ContentEditingService(IContentService contentService, IContentTypeService contentTypeService, PropertyEditorCollection propertyEditorCollection, IDataTypeService dataTypeService, ITemplateService templateService, ILogger<ContentEditingService> logger, ICoreScopeProvider scopeProvider, IUserIdKeyResolver userIdKeyResolver, ITreeEntitySortingService treeEntitySortingService, IContentValidationService contentValidationService, IUserService userService, ILanguageService languageService, IOptionsMonitor<ContentSettings> optionsMonitor, IRelationService relationService, ContentTypeFilterCollection contentTypeFilters)
		: base(contentService, contentTypeService, propertyEditorCollection, dataTypeService, (ILogger<ContentEditingServiceBase<IContent, IContentType, IContentService, IContentTypeService>>)logger, scopeProvider, userIdKeyResolver, (IContentValidationServiceBase<IContentType>)contentValidationService, treeEntitySortingService, optionsMonitor, relationService, contentTypeFilters, languageService, userService)
	{
		_templateService = templateService;
		_logger = logger;
	}

	/// <inheritdoc />
	public override Task<IContent?> GetAsync(Guid key)
	{
		return Task.FromResult(base.ContentService.GetById(key));
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentValidationResult, ContentEditingOperationStatus>> ValidateUpdateAsync(Guid key, ValidateContentUpdateModel updateModel, Guid userKey)
	{
		IContent byId = base.ContentService.GetById(key);
		return (byId == null) ? Attempt.FailWithStatus(ContentEditingOperationStatus.NotFound, new ContentValidationResult()) : (await ValidateCulturesAndPropertiesAsync(updateModel, byId.ContentType.Key, updateModel.Cultures, userKey));
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentValidationResult, ContentEditingOperationStatus>> ValidateCreateAsync(ContentCreateModel createModel, Guid userKey)
	{
		ContentEditingOperationStatus contentEditingOperationStatus = await ValidateCreationAllowedAsync(createModel);
		if (contentEditingOperationStatus != ContentEditingOperationStatus.Success)
		{
			return Attempt.FailWithStatus(contentEditingOperationStatus, new ContentValidationResult());
		}
		return await ValidateCulturesAndPropertiesAsync(createModel, createModel.ContentTypeKey, createModel.Variants.Select((VariantModel variant) => variant.Culture), userKey);
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentCreateResult, ContentEditingOperationStatus>> CreateAsync(ContentCreateModel createModel, Guid userKey)
	{
		return await HandleCreateAsync(createModel, null, userKey);
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentCreateResult, ContentEditingOperationStatus>> CreateAndPublishAsync(ContentCreateModel createModel, string[] culturesToPublish, Guid userKey)
	{
		return await HandleCreateAsync(createModel, culturesToPublish, userKey);
	}

	private async Task<Attempt<ContentCreateResult, ContentEditingOperationStatus>> HandleCreateAsync(ContentCreateModel createModel, string[]? culturesToPublish, Guid userKey)
	{
		if (!(await ValidateCulturesAsync(createModel)))
		{
			return Attempt.FailWithStatus(ContentEditingOperationStatus.InvalidCulture, new ContentCreateResult());
		}
		Attempt<ContentCreateResult, ContentEditingOperationStatus> result = await MapCreate<ContentCreateResult>(createModel);
		if (!result.Success)
		{
			return result;
		}
		ContentEditingOperationStatus validationStatus = result.Status;
		ContentValidationResult validationResult = result.Result.ValidationResult;
		IContent content = await EnsureOnlyAllowedFieldsAreUpdated(result.Result.Content, userKey);
		ContentEditingOperationStatus contentEditingOperationStatus = await UpdateTemplateAsync(content, createModel.TemplateKey);
		if (contentEditingOperationStatus != ContentEditingOperationStatus.Success)
		{
			return Attempt.FailWithStatus(contentEditingOperationStatus, new ContentCreateResult
			{
				Content = content
			});
		}
		ContentEditingOperationStatus contentEditingOperationStatus2 = ((culturesToPublish != null) ? (await SaveAndPublish(content, culturesToPublish, userKey)) : (await Save(content, userKey)));
		ContentEditingOperationStatus contentEditingOperationStatus3 = contentEditingOperationStatus2;
		return (contentEditingOperationStatus3 == ContentEditingOperationStatus.Success) ? Attempt.SucceedWithStatus(validationStatus, new ContentCreateResult
		{
			Content = content,
			ValidationResult = validationResult
		}) : Attempt.FailWithStatus(contentEditingOperationStatus3, new ContentCreateResult
		{
			Content = content
		});
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentUpdateResult, ContentEditingOperationStatus>> UpdateAsync(Guid key, ContentUpdateModel updateModel, Guid userKey)
	{
		return await HandleUpdateAsync(key, updateModel, null, userKey);
	}

	/// <inheritdoc />
	public async Task<Attempt<ContentUpdateResult, ContentEditingOperationStatus>> UpdateAndPublishAsync(Guid key, ContentUpdateModel updateModel, string[] culturesToPublish, Guid userKey)
	{
		return await HandleUpdateAsync(key, updateModel, culturesToPublish, userKey);
	}

	private async Task<Attempt<ContentUpdateResult, ContentEditingOperationStatus>> HandleUpdateAsync(Guid key, ContentUpdateModel updateModel, string[]? culturesToPublish, Guid userKey)
	{
		IContent content = base.ContentService.GetById(key);
		if (content == null)
		{
			return Attempt.FailWithStatus(ContentEditingOperationStatus.NotFound, new ContentUpdateResult());
		}
		if (!(await ValidateCulturesAsync(updateModel)))
		{
			return Attempt.FailWithStatus(ContentEditingOperationStatus.InvalidCulture, new ContentUpdateResult
			{
				Content = content
			});
		}
		Attempt<ContentUpdateResult, ContentEditingOperationStatus> attempt = await MapUpdate<ContentUpdateResult>(content, updateModel);
		if (!attempt.Success)
		{
			return Attempt.FailWithStatus(attempt.Status, attempt.Result);
		}
		ContentEditingOperationStatus validationStatus = attempt.Status;
		ContentValidationResult validationResult = attempt.Result.ValidationResult;
		content = await EnsureOnlyAllowedFieldsAreUpdated(content, userKey);
		ContentEditingOperationStatus contentEditingOperationStatus = await UpdateTemplateAsync(content, updateModel.TemplateKey);
		if (contentEditingOperationStatus != ContentEditingOperationStatus.Success)
		{
			return Attempt.FailWithStatus(contentEditingOperationStatus, new ContentUpdateResult
			{
				Content = content
			});
		}
		ContentEditingOperationStatus contentEditingOperationStatus2 = ((culturesToPublish != null) ? (await SaveAndPublish(content, culturesToPublish, userKey)) : (await Save(content, userKey)));
		ContentEditingOperationStatus contentEditingOperationStatus3 = contentEditingOperationStatus2;
		return (contentEditingOperationStatus3 == ContentEditingOperationStatus.Success) ? Attempt.SucceedWithStatus(validationStatus, new ContentUpdateResult
		{
			Content = content,
			ValidationResult = validationResult
		}) : Attempt.FailWithStatus(contentEditingOperationStatus3, new ContentUpdateResult
		{
			Content = content
		});
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> MoveToRecycleBinAsync(Guid key, Guid userKey)
	{
		return await HandleMoveToRecycleBinAsync(key, userKey);
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> DeleteFromRecycleBinAsync(Guid key, Guid userKey)
	{
		return await HandleDeleteAsync(key, userKey);
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> DeleteAsync(Guid key, Guid userKey)
	{
		return await HandleDeleteAsync(key, userKey, mustBeTrashed: false);
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> MoveAsync(Guid key, Guid? parentKey, Guid userKey)
	{
		return await HandleMoveAsync(key, parentKey, userKey);
	}

	/// <inheritdoc />
	[Obsolete("Use the overload that takes an includeDescendants parameter instead. Scheduled for removal in Umbraco 19.")]
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> RestoreAsync(Guid key, Guid? parentKey, Guid userKey)
	{
		return await RestoreAsync(key, parentKey, userKey, includeDescendants: true);
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> RestoreAsync(Guid key, Guid? parentKey, Guid userKey, bool includeDescendants)
	{
		return await HandleMoveAsync(key, parentKey, userKey, mustBeInRecycleBin: true, includeDescendants);
	}

	/// <inheritdoc />
	public async Task<Attempt<IContent?, ContentEditingOperationStatus>> CopyAsync(Guid key, Guid? parentKey, bool relateToOriginal, bool includeDescendants, Guid userKey)
	{
		return await HandleCopyAsync(key, parentKey, relateToOriginal, includeDescendants, userKey);
	}

	/// <inheritdoc />
	public async Task<ContentEditingOperationStatus> SortAsync(Guid? parentKey, IEnumerable<SortingModel> sortingModels, Guid userKey)
	{
		return await HandleSortAsync(parentKey, sortingModels, userKey);
	}

	/// <inheritdoc />
	public async Task<ContentEditingOperationStatus> SortByFieldAsync(Guid? parentKey, ContentSortField field, Direction direction, string? culture, Guid userKey)
	{
		return await HandleSortByFieldAsync(parentKey, field, direction, culture, userKey);
	}

	private async Task<ContentEditingOperationStatus> UpdateTemplateAsync(IContent content, Guid? templateKey)
	{
		if (!templateKey.HasValue)
		{
			content.TemplateId = null;
			return ContentEditingOperationStatus.Success;
		}
		ITemplate template = await _templateService.GetAsync(templateKey.Value);
		if (template == null)
		{
			return ContentEditingOperationStatus.TemplateNotFound;
		}
		if (!(base.ContentTypeService.Get(content.ContentTypeId) ?? throw new ArgumentException("The content type was not found", "content")).IsAllowedTemplate(template.Alias))
		{
			return ContentEditingOperationStatus.TemplateNotAllowed;
		}
		content.TemplateId = template.Id;
		return ContentEditingOperationStatus.Success;
	}

	/// <inheritdoc />
	protected override IContent New(string name, int parentId, IContentType contentType)
	{
		return new Content(name, parentId, contentType);
	}

	/// <inheritdoc />
	protected override OperationResult? Move(IContent content, int newParentId, bool includeDescendants, int userId)
	{
		return base.ContentService.Move(content, newParentId, includeDescendants, userId);
	}

	/// <inheritdoc />
	protected override async Task<IContent?> CopyAsync(IContent content, int newParentId, bool relateToOriginal, bool includeDescendants, Guid userKey)
	{
		int userId = await GetUserIdAsync(userKey);
		return base.ContentService.Copy(content, newParentId, relateToOriginal, includeDescendants, userId);
	}

	/// <inheritdoc />
	protected override OperationResult? MoveToRecycleBin(IContent content, int userId)
	{
		return base.ContentService.MoveToRecycleBin(content, userId);
	}

	/// <inheritdoc />
	protected override OperationResult? Delete(IContent content, int userId)
	{
		return base.ContentService.Delete(content, userId);
	}

	/// <inheritdoc />
	protected override IEnumerable<IContent> GetPagedChildren(int parentId, int pageIndex, int pageSize, Ordering? ordering, out long total)
	{
		return base.ContentService.GetPagedChildren(parentId, pageIndex, pageSize, out total, null, null, ordering);
	}

	/// <inheritdoc />
	protected override ContentEditingOperationStatus Sort(IEnumerable<IContent> items, int userId)
	{
		OperationResult operationResult = base.ContentService.Sort(items, userId);
		return OperationResultToOperationStatus(operationResult);
	}

	/// <inheritdoc />
	protected override ContentEditingOperationStatus SortChildrenInBulk(int parentId, IReadOnlyList<int> orderedChildIds, int userId)
	{
		OperationResult operationResult = base.ContentService.SortChildren(parentId, orderedChildIds, userId);
		return OperationResultToOperationStatus(operationResult);
	}

	private async Task<ContentEditingOperationStatus> Save(IContent content, Guid userKey)
	{
		try
		{
			int value = await GetUserIdAsync(userKey);
			return base.ContentService.Save(content, value).Result switch
			{
				OperationResultType.Success => ContentEditingOperationStatus.Success, 
				OperationResultType.FailedCancelledByEvent => ContentEditingOperationStatus.CancelledByNotification, 
				_ => ContentEditingOperationStatus.Unknown, 
			};
		}
		catch (Exception exception)
		{
			_logger.LogError(exception, "Content save operation failed");
			return ContentEditingOperationStatus.Unknown;
		}
	}

	private async Task<ContentEditingOperationStatus> SaveAndPublish(IContent content, string[] culturesToPublish, Guid userKey)
	{
		try
		{
			int userId = await GetUserIdAsync(userKey);
			PublishResult publishResult = base.ContentService.SaveAndPublish(content, culturesToPublish, userId);
			if (publishResult.Success)
			{
				return ContentEditingOperationStatus.Success;
			}
			return (publishResult.Result == PublishResultType.FailedPublishCancelledByEvent) ? ContentEditingOperationStatus.CancelledByNotification : ContentEditingOperationStatus.Unknown;
		}
		catch (Exception exception)
		{
			_logger.LogError(exception, "Content save and publish operation failed");
			return ContentEditingOperationStatus.Unknown;
		}
	}
}

