protected async Task<Attempt<TContentUpdateResult, ContentEditingOperationStatus>> MapUpdate<TContentUpdateResult>(TContent content, ContentEditingModelBase contentEditingModelBase) where TContentUpdateResult : ContentUpdateResultBase<TContent>, new()
{
	TContentType contentType = TryGetAndValidateContentType(content.ContentType.Key, contentEditingModelBase, out var operationStatus);
	if (contentType == null)
	{
		return Attempt.FailWithStatus(operationStatus, new TContentUpdateResult
		{
			Content = content
		});
	}
	Attempt<ContentValidationResult, ContentEditingOperationStatus> validationResult = await ValidatePropertiesAsync(contentEditingModelBase, contentType);
	UpdateNames(contentEditingModelBase, content, contentType);
	await UpdateExistingProperties(contentEditingModelBase, content, contentType);
	RemoveMissingProperties(contentEditingModelBase, content, contentType);
	return Attempt.SucceedWithStatus(validationResult.Status, new TContentUpdateResult
	{
		Content = content,
		ValidationResult = validationResult.Result
	});
}

/// <summary>
/// Validates the cultures in the content editing model.
/// </summary>
/// <param name="contentEditingModelBase">The content editing model to validate.</param>
/// <returns><c>true</c> if all cultures are valid; otherwise, <c>false</c>.</returns>
protected async Task<bool> ValidateCulturesAsync(ContentEditingModelBase contentEditingModelBase)
{
	return await _validationService.ValidateCulturesAsync(contentEditingModelBase);
}

protected async Task<Attempt<ContentValidationResult, ContentEditingOperationStatus>> ValidateCulturesAndPropertiesAsync(ContentEditingModelBase contentEditingModelBase, Guid contentTypeKey, IEnumerable<string?>? cultures, Guid userKey)
{
	if (!(await ValidateCulturesAsync(contentEditingModelBase)))
	{
		return Attempt.FailWithStatus(ContentEditingOperationStatus.InvalidCulture, new ContentValidationResult());
	}
	return await ValidatePropertiesAsync(contentEditingModelBase, contentTypeKey, await GetCulturesToValidate(cultures, userKey));
}

/// <summary>
/// Validates the properties in the content editing model against the content type.
/// </summary>
/// <param name="contentEditingModelBase">The content editing model to validate.</param>
/// <param name="contentTypeKey">The content type key.</param>
/// <param name="culturesToValidate">Optional cultures to restrict validation to.</param>
/// <returns>An attempt containing the validation result and operation status.</returns>
protected async Task<Attempt<ContentValidationResult, ContentEditingOperationStatus>> ValidatePropertiesAsync(ContentEditingModelBase contentEditingModelBase, Guid contentTypeKey, IEnumerable<string?>? culturesToValidate = null)
{
	TContentType val = await ContentTypeService.GetAsync(contentTypeKey);
	if (val == null)
	{
		return Attempt.FailWithStatus(ContentEditingOperationStatus.ContentTypeNotFound, new ContentValidationResult());
	}
	return await ValidatePropertiesAsync(contentEditingModelBase, val, culturesToValidate);

