var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// Check umbracoContent - what's in it?
Console.WriteLine("=== All umbracoContent ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT * FROM umbracoContent";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"nodeId={r.GetInt32(0)} contentTypeId={r.GetInt32(1)}");
}

