using Microsoft.Data.Sqlite;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// Property types for blogFrontPage (contentType nodeId=1092) and blogPost (contentType nodeId=1093)
Console.WriteLine("=== PropertyTypes for blogFrontPage (nodeId=1092) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT id, Alias, Name, dataTypeId FROM cmsPropertyType WHERE contentTypeId = 1092 ORDER BY Alias";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"id={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dataTypeId={r.GetInt32(3)}");
}

Console.WriteLine("\n=== PropertyTypes for blogPost (nodeId=1093) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT id, Alias, Name, dataTypeId FROM cmsPropertyType WHERE contentTypeId = 1093 ORDER BY Alias";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"id={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dataTypeId={r.GetInt32(3)}");
}

// Check what block grid data types are used by these properties
Console.WriteLine("\n=== Data types used by blog properties ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT dt.nodeId, dt.propertyEditorAlias, dt.propertyEditorUiAlias
        FROM umbracoDataType dt
        WHERE dt.nodeId IN (
            SELECT pt.dataTypeId FROM cmsPropertyType pt WHERE pt.contentTypeId IN (1092, 1093)
        )
        ORDER BY dt.nodeId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"nodeId={r.GetInt32(0)} editor={r.GetString(1)} uiAlias={r.GetValue(2)}");
}

// Check: what's the block grid data type that the 'blocks' and 'content' properties use?
Console.WriteLine("\n=== Check 1090 block grid properties ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT pt.id, pt.Alias, pt.Name, pt.dataTypeId
        FROM cmsPropertyType pt
        WHERE pt.dataTypeId = 1090
        ORDER BY pt.id";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine($"ptId={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dataTypeId={r.GetInt32(3)}");
}

conn.Close();
