{
	Dictionary<string, IPropertyType> propertyTypesByAlias = GetPropertyTypesByAlias(contentType);
	PropertyValueModel[] array = contentEditingModelBase.Properties.Where((PropertyValueModel propertyValueModel) => propertyTypesByAlias.ContainsKey(propertyValueModel.Alias)).ToArray();
	PropertyValueModel[] array2 = array;
	foreach (PropertyValueModel propertyValue in array2)
	{
		if (!propertyTypesByAlias.TryGetValue(propertyValue.Alias, out IPropertyType value) || (value.VariesByCulture() && propertyValue.Culture.IsNullOrWhiteSpace()) || (!value.VariesBySegment() && !propertyValue.Segment.IsNullOrWhiteSpace()))
		{
			throw new ArgumentException("Culture or segment variance mismatch for property: " + propertyValue.Alias, "contentEditingModelBase");
		}
		object value2 = await GetDataEditorValue(propertyValue.Value, propertyValue.Culture, propertyValue.Segment, value, content);
		content.SetValue(propertyValue.Alias, value2, propertyValue.Culture, propertyValue.Segment);
	}
}

private void RemoveMissingProperties(ContentEditingModelBase contentEditingModelBase, TContent content, TContentType contentType)
{
	Dictionary<string, IPropertyType> propertyTypesByAlias = GetPropertyTypesByAlias(contentType);
