namespace Umbraco.Cms.Infrastructure.HybridCache.SeedKeyProviders.Element;

internal sealed class ElementContentTypeSeedKeyProvider : IElementSeedKeyProvider, ISeedKeyProvider
{
	private readonly ICoreScopeProvider _scopeProvider;

	private readonly IDatabaseCacheRepository _databaseCacheRepository;

	private readonly IElementPublishStatusQueryService _publishStatusService;

	private readonly CacheSettings _cacheSettings;

	public ElementContentTypeSeedKeyProvider(ICoreScopeProvider scopeProvider, IDatabaseCacheRepository databaseCacheRepository, IOptions<CacheSettings> cacheSettings, IElementPublishStatusQueryService publishStatusService)
	{
		_scopeProvider = scopeProvider;
		_databaseCacheRepository = databaseCacheRepository;
		_publishStatusService = publishStatusService;
		_cacheSettings = cacheSettings.Value;
	}

	public ISet<Guid> GetSeedKeys()
	{
		ICoreScope val = _scopeProvider.CreateCoreScope(IsolationLevel.Unspecified, (RepositoryCacheMode)0, (IEventDispatcher)null, (IScopedNotificationPublisher)null, (bool?)null, false, false);
		try
		{
			HashSet<Guid> result = (from key in _databaseCacheRepository.GetElementKeysByContentTypeKeys(_cacheSettings.ContentTypeKeys, published: true)
				where _publishStatusService.IsPublishedInAnyCulture(key)
				select key).ToHashSet();
			val.Complete();
			return result;
		}
		finally
		{
			((IDisposable)val)?.Dispose();
		}
	}
}
