	public async Task<ContentCacheNode?> GetElementSourceAsync(Guid key, bool preview = false)
	{
		ContentSourceDto contentSourceDto = await GetElementSourceDto(key);
		if (contentSourceDto == null)
		{
			return null;
		}
		if (!preview && contentSourceDto.PubDataRaw == null && contentSourceDto.PubData == null)
		{
			return null;
		}
		if (!preview && contentSourceDto.Published && contentSourceDto.PubName == null)
		{
			_logger.LogWarning("Node {NodeKey} appears published but has no published version name, indicating an inconsistent database state. Consider republishing the content. Skipping node.", key);
			return null;
		}
		return CreateElementNodeKit(preview, contentSourceDto);
	}

	public async Task<(ContentCacheNode? Draft, ContentCacheNode? Published)> GetElementSourceForPublishStatesAsync(Guid key)
	{
		ContentSourceDto contentSourceDto = await GetElementSourceDto(key);
		if (contentSourceDto == null)
		{
			return (Draft: null, Published: null);
		}
		ContentCacheNode item = CreateElementNodeKit(preview: true, contentSourceDto);
		ContentCacheNode item2;
		if (contentSourceDto.PubDataRaw == null && contentSourceDto.PubData == null)
		{
			item2 = null;
		}
		else if (contentSourceDto.Published && contentSourceDto.PubName == null)
		{
			_logger.LogWarning("Node {NodeKey} appears published but has no published version name, indicating an inconsistent database state. Consider republishing the content. Skipping node.", key);
			item2 = null;
		}
		else
		{
			item2 = CreateElementNodeKit(preview: false, contentSourceDto);
		}
		return (Draft: item, Published: item2);
	}

