conn.Open();

// cmsContentNu - all entries
Console.WriteLine("=== cmsContentNu - all entries ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT nodeId, published, length(data) as dataLen, length(dataRaw) as rawLen FROM cmsContentNu ORDER BY nodeId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"nodeId={r.GetInt32(0)} published={r.GetInt32(1)} dataLen={r.GetValue(2)} rawLen={r.GetValue(3)}");
    }
}

// Dump the dataRaw for blogPost nodeId=1103 to see actual content
Console.WriteLine("\n=== dataRaw hex dump for nodeId=1103 (blogPost published) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT dataRaw FROM cmsContentNu WHERE nodeId=1103 AND published=1";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        byte[] raw = (byte[])r.GetValue(0);
        // Print first 300 bytes as hex and ASCII
        int len = Math.Min(raw.Length, 300);
        for (int i = 0; i < len; i += 16) {
            Console.Write($"{i:X4}: ");
            for (int j = 0; j < 16 && i + j < len; j++) {
                Console.Write($"{raw[i+j]:X2} ");
            }
            Console.Write("  ");
            for (int j = 0; j < 16 && i + j < len; j++) {
                char c = (char)raw[i+j];
                Console.Write(char.IsControl(c) ? '.' : c);
            }
            Console.WriteLine();
        }
    }
}

// What are the actual documentVersionIds for our blog posts?
Console.WriteLine("\n=== blog post document versions ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT dv.id, dv.versionId, dv.documentId, dv.published, dv.current, un.text as name
        FROM umbracoDocumentVersion dv
        JOIN umbracoNode un ON un.id = dv.documentId
        WHERE dv.documentId IN (1102, 1103, 1104)
        ORDER BY dv.documentId, dv.id";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"dvId={r.GetInt32(0)} verId={r.GetValue(1)} docId={r.GetInt32(2)} pub={r.GetInt32(3)} cur={r.GetInt32(4)} name={r.GetString(5)}");
    }
}

// Check all property types for the blogPost document type
Console.WriteLine("\n=== All property types for blogPost (contentTypeId=1092) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT pt.id, pt.Alias, pt.Name, pt.dataTypeId, pt.sortOrder
        FROM cmsPropertyType pt
        JOIN umbracoNode un ON un.id = pt.contentTypeId
        WHERE un.uniqueId = (SELECT uniqueId FROM umbracoNode WHERE id=1092)
        ORDER BY pt.sortOrder";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"ptId={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dataTypeId={r.GetInt32(3)} sortOrder={r.GetInt32(4)}");
    }
}

// Check umbracoPropertyData - look for entries with the block grid property type ids
Console.WriteLine("\n=== umbracoPropertyData for block properties (all) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT up.Id, up.documentVersionId, up.languageId, up.propertyTypeId,
               length(up.textValue) as tvLen, substring(up.textValue, 1, 200) as tvPreview
        FROM umbracoPropertyData up
        WHERE up.propertyTypeId IN (
            SELECT id FROM cmsPropertyType
            WHERE contentTypeId IN (SELECT nodeId FROM cmsContentType WHERE alias='blogPost')
        )";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"id={r.GetInt32(0)} docVerId={r.GetInt32(1)} lang={r.GetValue(2)} ptId={r.GetInt32(3)} tvLen={r.GetValue(4)}");
