using Microsoft.Data.Sqlite;
using System.Text;
var dbPath = @"X:\code\umbraco-benchmark\Umbraco.Bench\Umbraco.Bench.Umbraco\umbraco\Data\Umbraco.sqlite.db";
var connString = new SqliteConnectionStringBuilder { DataSource = dbPath }.ToString();
using var conn = new SqliteConnection(connString);
conn.Open();

// cmsContentNu - all entries
Console.WriteLine("=== cmsContentNu - all entries ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT nodeId, published, length(data) as dataLen, length(dataRaw) as rawLen FROM cmsContentNu ORDER BY nodeId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"nodeId={r.GetInt32(0)} published={r.GetInt32(1)} dataLen={r.GetValue(2)} rawLen={r.GetValue(3)}");
    }
}

// Element content type keys
Console.WriteLine("\n=== Element content type GUIDs (for CacheSettings.ContentTypeKeys) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT ct.nodeId, ct.alias, un.uniqueId
        FROM cmsContentType ct
        JOIN umbracoNode un ON un.id = ct.nodeId
        WHERE ct.isElement = 1
        ORDER BY ct.alias";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"nodeId={r.GetInt32(0)} alias={r.GetString(1)} uniqueId={r.GetGuid(2)}");
    }
}

// Document content type keys
Console.WriteLine("\n=== Document content type GUIDs ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT ct.nodeId, ct.alias, un.uniqueId
        FROM cmsContentType ct
        JOIN umbracoNode un ON un.id = ct.nodeId
        WHERE ct.isElement = 0
        ORDER BY ct.alias";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"nodeId={r.GetInt32(0)} alias={r.GetString(1)} uniqueId={r.GetGuid(2)}");
    }
}

// Content types and data types for block grid
Console.WriteLine("\n=== Data type for block grid ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT un.id, un.uniqueId, un.text as name
        FROM umbracoNode un
        WHERE un.id IN (SELECT nodeId FROM umbracoDataType WHERE nodeId=1090)";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"id={r.GetInt32(0)} uniqueId={r.GetGuid(1)} name={r.GetString(2)}");
    }
}

// Check all property type aliases for blogPost content type
Console.WriteLine("\n=== Property types for blogPost document type (nodeId=1092) ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT pt.id, pt.Alias, pt.Name, pt.dataTypeId, un2.text as dataTypeName
        FROM cmsPropertyType pt
        JOIN umbracoNode un ON un.id = pt.contentTypeId
        JOIN umbracoNode un2 ON un2.id = pt.dataTypeId
        WHERE un.uniqueId = (SELECT uniqueId FROM umbracoNode WHERE id=1092)
        ORDER BY pt.sortOrder";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        Console.WriteLine($"ptId={r.GetInt32(0)} alias={r.GetString(1)} name={r.GetValue(2)} dtId={r.GetInt32(3)} dtName={r.GetString(4)}");
    }
}

// The key query: what document types are associated with the block grid data type
Console.WriteLine("\n=== All content types that have properties using block grid data type 1090 ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT c.alias as contentTypeAlias, pt.Alias as propAlias, pt.Name as propName
        FROM cmsPropertyType pt
        JOIN cmsContentType c ON c.nodeId = pt.contentTypeId
        WHERE pt.dataTypeId = 1090";
