Console.WriteLine("=== Tables matching '%template%' ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%template%' ORDER BY name";
    using var r = cmd.ExecuteReader();
    while (r.Read()) Console.WriteLine(r.GetString(0));
}

// Check DocumentVersion columns
Console.WriteLine("\n=== umbracoDocumentVersion all data ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = "SELECT * FROM umbracoDocumentVersion";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        for (int i = 0; i < r.FieldCount; i++) 
            Console.Write($"  {r.GetName(i)}={r.GetValue(i)}");
        Console.WriteLine();
    }
}

// Map version IDs to nodes via ContentVersion
Console.WriteLine("\n=== Map property data versions to nodes ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT up.versionId, cv.nodeId, un.text as name, ct.alias as type
        FROM umbracoPropertyData up
        JOIN umbracoContentVersion cv ON cv.id = up.versionId
        JOIN umbracoNode un ON un.id = cv.nodeId
        JOIN cmsContentType ct ON ct.nodeId = (SELECT contentTypeId FROM umbracoContent WHERE nodeId = cv.nodeId)
        GROUP BY up.versionId
        ORDER BY up.versionId";
    using var r = cmd.ExecuteReader();
    while (r.Read()) 
        Console.WriteLine($"verId={r.GetValue(0)} nodeId={r.GetInt32(1)} name={r.GetString(2)} type={r.GetString(3)}");
}

// Content version table data
Console.WriteLine("\n=== umbracoContentVersion data for blog posts ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT cv.id, cv.versionDate, cv.current, cv.text, un.text as nodeName
        FROM umbracoContentVersion cv
        JOIN umbracoNode un ON un.id = cv.nodeId
        WHERE cv.nodeId IN (1102, 1103, 1104)
        ORDER BY cv.nodeId, cv.id";
    using var r = cmd.ExecuteReader();
    while (r.Read())
        Console.WriteLine($"id={r.GetValue(0)} date={r.GetString(1)} cur={r.GetValue(2)} text={r.GetString(3)} nodeName={r.GetString(4)}");
}

// Get the full 'content' block value
Console.WriteLine("\n=== Full 'content' block property value for blogPost ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT up.textValue FROM umbracoPropertyData up
        JOIN cmsPropertyType pt ON pt.id = up.propertyTypeId
        WHERE pt.alias = 'content' AND up.textValue IS NOT NULL
        LIMIT 1";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        string val = r.GetString(0);
        Console.WriteLine($"Length: {val.Length}");
        Console.WriteLine(val);
    }
}

// Get the 'blocks' block property value for blogFrontPage
Console.WriteLine("\n=== 'blocks' block property value for blogFrontPage ===");
using (var cmd = conn.CreateCommand()) {
    cmd.CommandText = @"
        SELECT up.textValue FROM umbracoPropertyData up
        JOIN cmsPropertyType pt ON pt.id = up.propertyTypeId
        WHERE pt.alias = 'blocks' AND up.textValue IS NOT NULL
        LIMIT 1";
    using var r = cmd.ExecuteReader();
    while (r.Read()) {
        string val = r.GetString(0);
        Console.WriteLine($"Length: {val.Length}");
        Console.WriteLine(val);
    }
}

conn.Close();
